import json

url = "https://partner.shopeemobile.com/api/v2/ams/update_auto_add_new_product_setting?access_token=access_token&partner_id=partner_id&shop_id=shop_id&sign=sign&timestamp=timestamp"

payload=json.dumps({
  "commission_rate": 1.1,
  "open": True
})
headers = {
  'Content-Type': 'application/json'
}
response = requests.RPCRequest("POST",url,headers=headers, data=payload, allow_redirects=False)

print(response.text)

